        + [M("Which pronouns are used in requests with doer-focus verbs?", "ka and kayo", ["mo and ninyo", "ko and namin", "ako and kami"], "ka at kayo."), M("Which pronouns are used with object-focus verbs?", "mo and ninyo", ["ka and kayo", "ako and kami", "tayo only"], "mo at ninyo."), M("What is the doer-focus form of us in Let us plus V?", "tayo", ["natin", "namin", "kami"], "tayo."), M("What is the object-focus form of us in Let us plus V?", "natin", ["tayo", "kami", "namin"], "natin."), M("What is the negative of Let us plus V?", "huwag tayong", ["bawal tayo", "hindi tayo", "baka tayo"], "huwag tayong."), M("What does Mabilis lumakad si Victor mean?", "Victor walks fast", ["Victor walked slowly", "Victor will walk", "Victor stopped"], "mabilis lumakad."), M("What does Nagluto nang mabuti si Elvira mean?", "Elvira cooked well", ["Elvira cooks well", "Elvira will cook", "Elvira cannot cook"], "nagluto nang mabuti."), M("What does Magaling magluto si Elvira mean?", "Elvira cooks well", ["Elvira cooked well", "Elvira will cook", "Elvira cannot cook"], "magaling magluto."), M("What does Mahusay magsalita si Willie mean?", "Willie speaks well", ["Willie spoke well", "Willie will speak", "Willie is silent"], "mahusay magsalita."), M("Which words are time conjunctions that take the infinitive?", "bago and pagkatapos", ["para and upang", "baka and sana", "huwag and bawal"], "bago, pagkatapos."), M("Which set of pronouns does pagkatapos always use for the doer?", "second set", ["first set", "third set", "none"], "pagkatapos nilang."), M("What does Siguruhin mong ligtas ang mga mahihirap mean?", "ensure that the poor are safe", ["the poor are in danger", "the poor are rich", "ask the poor to leave"], "siguruhin."), M("What does Nang sumali kami sa Pantawid Pamilya, bumuti ang buhay namin mean?", "when we joined Pantawid Pamilya, our lives improved", ["we left Pantawid Pamilya", "our lives became worse", "we will join next year"], "nang sumali."), M("What does bago ka makatanggap ng tulong mean?", "before you can receive help", ["after you receive help", "if you give help", "because you help"], "bago.")]
        + [F("___ tayo nang maaga araw-araw. (let us go to work)", "Pumasok", ["Pumasok kayo", "Papasok"], "pumasok tayo."), F("Siguruhin ___ magkaroon sila ng kabutihang-asal. (you, linker)", "mong", ["natin", "niyong"], "mong."), F("Bago ___ makatanggap ng tulong, sumunod ka sa mga kondisyon. (you)", "ka", ["mo", "nila"], "bago ka."), F("Pagkatapos ___ mag-aral, huwag kang matulog. (they)", "nilang", ["silang", "kayong"], "nilang.")]
