        card("Activity 7: the book’s chart", "", tables=[table(["Year", "Number of cases filed"], _C7, say=[])]),
        card("Activity 8: a news report about an initiative by a church organization", "Source: remate.ph (Huwag kang magnakaw campaign, suportahan, Tagle), 2015. In the spoken text the quotation marks around the campaign name are dropped.", examples=passage(_A8)),
        card("Activity 8: the book’s key (main idea and supporting details)", "The book misspells Tagle and Adamson in its key (“tagle,” “Admason”); corrected.", tables=[table(["", "Detail"], [list(r) for r in _K8], say=[])]),
        card("Activity 9: messages of DSWD student-scholar-beneficiaries to the Filipino youth (the book’s scripts)", "Listen and fill in the chart with the gist of each speaker’s message. The speakers’ labels are Speaker One, Two and Three in the spoken text. Speaker Two’s hesitation fillers (ano) are kept.", examples=dlg(_A9)),
