        card("Passage 2 (009): enforcing Philippine Standard Time", "Republic Act No. 10535 is written in words in the spoken text; “S1” and “S2” are Speaker One and Speaker Two, and the ellipsis after PhST is a comma.", examples=dlg(_L11D)),
