        + [M("What value does the teacher in Segment One want to share?", "honesty", ["wealth", "speed", "fame"], "katapatan."), M("What does being pro-God mean to the Segment Two speaker?", "putting God first in everything", ["avoiding work", "saving money", "traveling"], "Diyos ang unahin."), M("What is the second value in Segment Two?", "being helpful to one another", ["being rich", "being famous", "being quiet"], "matulungin."), M("What is the topic for November in Segment Three?", "the Moral Recovery Program", ["traffic rules", "tax filing", "elections"], "MRP."), M("What strength of Filipino character do the teachers want to share?", "pakikipagkapwa-tao", ["bahala na", "ningas-kugon", "crab mentality"], "pakikipagkapwatao."), M("What negative trait does Mamang Pulis at Aleng Pulis address?", "padrino system, bribery and extortion", ["Filipino time", "colonial mentality", "ningas-kugon only"], "reporma."), M("What is PhST?", "Philippine Standard Time", ["Philippine Summer Time", "Pacific Standard Time", "Private School Time"], "PhST."), M("Under what law is Philippine Standard Time enforced?", "Republic Act number ten thousand five hundred thirty-five", ["Republic Act number one", "Presidential Decree number ten", "Batas Pambansa number five"], "RA 10535."), M("Which trait does enforcing Philippine Standard Time address?", "Filipino time", ["colonial mentality", "bahala na", "padrino system"], "Filipino time."), M("How many students has the Training for Work Scholarship Program graduated?", "547,554", ["547,000", "55,000", "5,475"], "limandaan at apatnapu’t pito."), M("Which trait does the technical vocational program address?", "bahala na, passivity and feeling inferior", ["Filipino time", "padrino system", "lack of discipline"], "may awa ang Diyos pero nasa tao ang gawa."), M("Who led the strict street discipline in Manila?", "Vice Mayor Isko Moreno", ["Mayor Alfredo Lim", "Secretary Mar Roxas", "Senator Santiago"], "Isko Moreno."), M("What is the aim of the Buy Pinoy Program revival?", "to patronize local products instead of foreign ones", ["to ban imports", "to raise taxes", "to close markets"], "tangkilikin ang local."), M("What does One Good Vote aim to eradicate?", "vote buying, vote selling and the padrino system", ["traffic", "floods", "illiteracy"], "puksain.")]
