# ------------------------------------------------------------------ 9 activity 12, speaking, glossary
_A12 = [("Pantawid Pamilyang Pilipino Program", "Ang Pantawid Pamilyang Pilipino Program, ang pinaka-layunin, panatilihin ang mga bata sa eskuwelahan at panatilihing malusog. Kinakailangan nating idagdag din ang mga anak ng nasa Pantawid na kinse hanggang disi-otso. Kasi, noong nakaraang taon, ipinasa ng mga Kongreso, ng ating lehislatura na magdagdag para nang sa ganun, matulungan nating makatapos sila sa high school. Kasi may pag-aaral na kapag tapos ka ng high school mas malaki at mas maayos na trabaho ang makukuha mo.", "The main aim of the Pantawid Pamilyang Pilipino Program is to keep the children in school and keep them healthy. We also need to add the children of those in Pantawid, fifteen to eighteen. Because last year, Congress, our legislature, passed an addition so that we can help them finish high school. There are studies that when you are a high school graduate, you get a bigger and better job."), ("Community driven development", "Well, pangalawa, e, yung tinatawag nating community driven development. Ito naman, mga mahihirap na bayan, at may nakalaang pera para ang mismong mamamayan ang magsabi ano ang proyekto na makakatulong sa mga pangunahing problema nila, pero sila ang humahawak ng pera at sila rin ang nag-iimplementa nung proyekto.", "Well, second, the so-called community driven development. This is for poor towns, and money is set aside so that the citizens themselves say what project will help with their main problems, but they are the ones who handle the money and implement the project."), ("Sustainable livelihood program", "At iyong pangatlo, e, yung tinatawag nating sustainable livelihood program. So yan po ay mahigit tatlong daan at limampung libong pamilya na ang natulungan natin sa pamamagitan ng pagbigay ng kapasidad na magkaroon sila ng negosyo.", "And the third is the so-called sustainable livelihood program. So that has helped more than 350,000 families by giving them the capacity to have a business."), ("TESDA for Tambay", "Yung mga tambay, tinulungan natin sila, kasama ng TESDA, na makapag-aral at magkaroon ng panibagong kakayahan o livelihood para magkaroon sila ng trabaho at sila ay kumita na. At pinapahiram natin sila ng sampung libo bawat pamilya, walang kolateral, walang interes, isasauli mo sa dalawang taon. At ang aming karanasan, nasa walumpu’t limang porsiyento repayment rate kami, kasi alam nila na malaking bagay na maibalik nila dahil maibibigay namin na tulong yan sa iba pang mga pamilya.", "The tambay, we helped them, together with TESDA, to study and have new skills (livelihood) so that they have work and earn. And we lend them ten thousand per family, no collateral, no interest, to be returned in two years. And in our experience, we have around an 85 percent repayment rate, because they know it matters a lot that they pay back, since we can give that help to other families.")]
_K12 = [["Pantawid Pamilyang Pilipino Program", "Assistance to families in order to keep children in school and healthy; it also includes 15 to 18 year old children to ensure they finish high school (based on studies that high school graduates get better jobs and earn more)."], ["Community Driven Development", "Poor towns or communities determine the projects that will address the major problem they face. A budget is provided for the project, which they themselves manage and implement."], ["Sustainable Livelihood Program", "Families are given the means to have their own small businesses. To date over 350,000 families have been helped."], ["Technical Vocation Education through TESDA for Tambay", "For the jobless or tambay, TESDA provides the means for them to study technical vocational courses and have a livelihood. Each family can loan 10,000 pesos without collateral or interest, to be repaid in two years. The repayment rate is 85 percent because the beneficiary families know the money they pay back to the government will help other families like them."]]
_S13 = [("Ang Pantawid Pamilyang Pilipino Program o Four Ps ay isang dole out ng gobyerno ng Pilipinas sa mga mahihirap. Hindi ito makakatulong sa pag-unlad ng bansa. Nagiging dahilan pa ito nang katamaran at patuloy na pagsandal ng mga mahihirap sa pamahalaan.", "The Pantawid Pamilyang Pilipino Program or 4Ps is a dole-out of the Philippine government to the poor. It will not help the development of the country. It even becomes a cause of laziness and the continued reliance of the poor on the government."), ("Walang halaga ang Moral Recovery Program dahil hanggang ngayong patuloy ang korupsyon o pagnanakaw ng maraming pulitiko at opisyal ng gobyerno ng Pilipinas. Wala itong idudulot na maganda.", "The Moral Recovery Program is worthless because up to now the corruption, or stealing, of many politicians and officials of the Philippine government continues. It will bring nothing good.")]
_G = [("benepisyaryo", "beneficiary"), ("birtud", "virtue"), ("dignidad", "dignity"), ("gawing", "habit"), ("huli", "latter"), ("inihalal", "elected"), ("integridad", "integrity"), ("ipagbawal", "to prohibit"), ("itinakda", "set; imposed"), ("itinalaga", "appointed"), ("kabilang sa", "included"), ("kabutihang-asal at wastong pakikitungo", "good manners and right conduct"), ("kondisyon", "condition"), ("makamahirap", "pro-poor"), ("mapatibay", "to strengthen"), ("matulungan", "to help"), ("namumuhunan", "investing"), ("pag-aanalisa", "analysis"), ("pagbibigay ng kapangyarihan sa mga tao", "people empowerment"), ("paggalang", "respect"), ("pagkalinga", "caring"), ("pagmamalaki", "pride"), ("pagpapalaganap", "promoting"), ("pagpapapurga", "deworming"), ("pagrespeto sa kinauukulan", "respect for authority"), ("pagsusuri sa sarili", "self-reflection"), ("pagtitiwala sa sariling kakayahan", "self-reliance"), ("pananagutan", "accountability"), ("pundasyon", "foundation"), ("sa kalaunan", "in the future; later"), ("sambahayan", "household"), ("tugon", "answer")]
_SS = [("Mahalaga ang katapatan sa pamahalaan.", "Honesty is important in the government. (my sentence)"), ("Dapat tulungan ang mga mahihirap na magkaroon ng trabaho.", "The poor should be helped to have work. (my sentence)"), ("Kailangang sumunod ang mga benepisyaryo sa mga kondisyon.", "Beneficiaries must follow the conditions. (my sentence)")]
L9 = lesson(
    "C25 L3 · DSWD anti-poverty programs, speaking, glossary and the self-evaluation",
    "Pantawid · Community Driven Development · Sustainable Livelihood · TESDA for Tambay · Talasalitaan",
    requires=[],
    cards=[
        card("Activity 12: the Secretary of DSWD describes anti-poverty programs (the book’s script)", "Listen and describe what each program covers; check with a partner. The audio is left out. The scripts are printed in the spoken text with these changes: a stray (Well) is Well; the ellipses are commas; “Kongres” is Kongreso; 350,000 and 85% are in words; “2 years time” is dalawang taon. Source: YouTube.", examples=dlg(_A12)),
        card("Activity 12: the book’s descriptions", "", tables=[table(["Anti-poverty program", "Description"], _K12, say=[])]),
        card("Activity 13: group work, a controversial statement", "Form two groups. Each group gets a controversial statement, works on its topic for a given time and presents its opinion to the class. The group may agree or disagree with the statement and explain. The speaking should be equally divided among group members, and at the end the class decides which group defended the idea best. The two statements are given. Group work, left out.", examples=dlg([("Statement one", a, b) for a, b in _S13[:1]] + [("Statement two", a, b) for a, b in _S13[1:]])),
        card("Activity 14: individual work", "You are given key words reflecting virtues for the improvement of the government and generate ideas quickly, agreeing or disagreeing, giving examples or creating stories. The key words are the virtues of the MRP: kabutihang-asal at wastong pakikitungo sa iba, pagkalinga at pamamahagi, integridad at pananagutan, pagtitiwala sa sariling kakayahan, pagrespeto sa kinauukulan at mga institusyon, pagbibigay ng kapangyarihan sa mga tao, and pagsusuri sa sarili at pag-aanalisa. Individual speaking, left out."),
        card("My sample sentences", "", examples=passage(_SS)),
        card("Glossary", "The book marks ipagbawal as a noun and gives “set;imposed”; normalized here. “Kabilang sa” is the book’s prepositional entry; makamahirap is the book’s spelling of maka-mahirap.", tables=[ttable(_G)]),
        card("Self-evaluation", "Recall the objectives at the beginning of the lesson and mark Yes or No: extract information from reading and listening passages about initiatives addressing social and cultural issues; identify the features of the Moral Recovery Program and its mission; identify and discuss the features of the Pantawid Pamilyang Pilipino program; transcribe and translate phrases and sentences related to initiatives addressing social and other cultural issues. Features to check: other uses of the infinitive (pawatas). If you answered No, review the section, find a study partner, or tell your academic counselor or team leader."),
        card("Activities left out", "The audio, the mind map, the pair, group and individual speaking activities."),
    ],
    exercises=uniq(
        tr_q(P(_A12[:2])) + tr_q(P(_A12[2:])) + rev_q(P(_A12[:2])) + rev_q(P(_A12[2:])) + tr_q(_S13) + tr_q(_SS) + rev_q(_SS)
        + tr_q(_G[:11]) + tr_q(_G[11:22]) + tr_q(_G[22:]) + rev_q(_G[:8]) + rev_q(_G[8:16]) + rev_q(_G[16:24]) + rev_q(_G[24:])
        + [M(f"What does {a} mean?", b, dd([x[1] for x in _G], b), b + ".") for a, b in _G]
        + [M("What does the Pantawid program aim for, per the DSWD Secretary?", "keeping children in school and healthy", ["building roads", "paying taxes", "buying farms"], "panatilihin ang mga bata sa eskuwelahan."), M("Why was the Pantawid coverage extended to ages fifteen to eighteen?", "so they can finish high school", ["so they can work early", "so they can travel", "so they can marry"], "makatapos sa high school."), M("What does community driven development do?", "lets poor communities choose and manage their own projects", ["gives them food", "moves them to cities", "gives them land"], "sila ang humahawak ng pera."), M("How many families has the sustainable livelihood program helped?", "more than 350,000", ["more than 35,000", "more than 3,500", "more than 35"], "mahigit tatlong daan at limampung libo."), M("How much can each tambay family loan?", "ten thousand pesos without collateral or interest", ["one thousand pesos with interest", "a hundred thousand pesos with collateral", "nothing"], "sampung libo."), M("Within how long is the loan repaid?", "two years", ["two months", "ten years", "one week"], "dalawang taon."), M("What is the repayment rate?", "eighty-five percent", ["fifty percent", "ten percent", "one hundred percent"], "walumpu’t limang porsiyento."), M("Why do the families repay?", "the money helps other families like them", ["they fear the police", "they are forced", "they want a trophy"], "tulong sa iba pang pamilya."), M("What does the first Activity 13 statement call the 4Ps?", "a dole-out", ["a loan", "a prize", "a salary"], "dole out."), M("What does the second statement say about the MRP?", "it is worthless because corruption continues", ["it is a great success", "it is new", "it is cheap"], "walang halaga.")]
        + [F("Ang Pantawid Pamilyang Pilipino Program ay tumutulong sa mga ___. (the poor)", "mahihirap", ["mayayaman", "pulitiko"], "mahihirap."), F("May ___ na pera para sa proyekto ng mamamayan. (set aside)", "nakalaang", ["nakalimutang", "nakasulat na"], "nakalaang."), F("Pinapahiram natin sila ng sampung libo, walang ___. (collateral)", "kolateral", ["negosyo", "pamilya"], "kolateral."), F("Kailangang sumunod ang mga benepisyaryo sa mga ___. (conditions)", "kondisyon", ["pulitiko", "benepisyo"], "kondisyon.")]
    ),
)

